#include "led.h"
#include "timer.h"
#include "uart.h"
#include <stdint.h>
#include "stm32c031xx.h"

#include "uart.h"
#include "stm32c031xx.h"

int main(void)
{
    uart_init();

    uart_write_string("UART ready\r\n");

    while (1)
    {
        if (USART1->ISR & USART_ISR_RXNE_RXFNE)
        {
            uart_write_string("RX FLAG SET\r\n");
            uart_write_char(USART1->RDR);
        }
    }
}